Lemma chunk_join3 : forall mm a (A B C : list byte),
  rw_cells bsegs mm a [CB (length A) A] ->
  rw_cells bsegs mm (a + Z.of_nat (length A)) [CB (length B) B] ->
  rw_cells bsegs mm (a + Z.of_nat (length A) + Z.of_nat (length B)) [CB (length C) C] ->
  rw_cells bsegs mm a [CB (length (A ++ B ++ C)) (A ++ B ++ C)].
Proof.
  intros mm a A B C H1 H2 H3.
  pose proof (rw_cells_CB_join bsegs mm _ _ _ _ _ H2 H3) as H23.
  replace (a + Z.of_nat (length A) + Z.of_nat (length B)) with (a + Z.of_nat (length A) + Z.of_nat (length B)) in H23 by lia.
  pose proof (rw_cells_CB_join bsegs mm _ _ _ _ _ H1 ltac:(replace (Z.of_nat (length B + length C)) with (Z.of_nat (length B) + Z.of_nat (length C)) by lia; exact H23)) as H.
  rewrite !length_app. exact H.
Qed.

Lemma chunk_join3' : forall mm a nA nB nC (A B C : list byte),
  rw_cells bsegs mm a [CB nA A] ->
  rw_cells bsegs mm (a + Z.of_nat nA) [CB nB B] ->
  rw_cells bsegs mm (a + Z.of_nat nA + Z.of_nat nB) [CB nC C] ->
  rw_cells bsegs mm a [CB (nA + nB + nC)%nat (A ++ B ++ C)].
Proof.
  intros mm a nA nB nC A B C H1 H2 H3.
  pose proof (rw_cells_CB_join bsegs mm _ _ _ _ _ H2 H3) as H23.
  pose proof (rw_cells_CB_join bsegs mm _ _ _ _ _ H1 ltac:(replace (Z.of_nat (nB + nC)) with (Z.of_nat nB + Z.of_nat nC) by lia; exact H23)) as H.
  replace (nA + nB + nC)%nat with (nA + (nB + nC))%nat by lia. exact H.
Qed.

